package local.lito381.server;
import java.lang.ref.WeakReference;
/** Original companion Snapshot authority; no owner, actor, Context or pending action registry. */
final class NativeSourceCompanionFirstActor {
 record View(WeakReference<BattleCompanion> actor,Object life,WeakReference<Object> profile,NativeSourceNpcFactoryType.Stamp stamp,BattleCompanion.Kind kind,long id,int npc,int x,int y,int heading,long target){}
 static Object capture(BattleCompanion pet){if(!CombatRules.loaded())return null;if(!Thread.holdsLock(pet))throw new IllegalStateException("companion Snapshot lost original actor monitor");return new View(new WeakReference<>(pet),NativeCombatAttacker.token((BattleTimedStatus)CombatAccess.field(pet,"timedStatus"),true),new WeakReference<>(CombatAccess.field(pet,"profile")),NativeSourceNpcFactoryType.stamp(pet),(BattleCompanion.Kind)CombatAccess.field(pet,"kind"),(long)CombatAccess.field(pet,"objectId"),NativeSourceNpcFactoryMemory.npc(pet),(int)CombatAccess.field(pet,"x"),(int)CombatAccess.field(pet,"y"),(int)CombatAccess.field(pet,"heading"),(long)CombatAccess.field(pet,"targetObjectId"));}
 static Object raw(Object snapshot){return snapshot instanceof BattleCompanion.Snapshot s?s.nativeSourceCompanionFirstActor:null;}
 static boolean identity(View v,BattleCompanion pet){return pet!=null&&v.actor().get()==pet&&v.profile().get()==CombatAccess.field(pet,"profile")&&v.stamp()==NativeSourceNpcFactoryType.stamp(pet)&&v.kind()==CombatAccess.field(pet,"kind")&&v.id()==(long)CombatAccess.field(pet,"objectId")&&v.npc()==NativeSourceNpcFactoryMemory.npc(pet);}
 static boolean same(View v,BattleCompanion pet){return identity(v,pet)&&v.life()==NativeCombatAttacker.token((BattleTimedStatus)CombatAccess.field(pet,"timedStatus"),false);}
 static boolean coherent(View v,Object snapshot){return snapshot instanceof BattleCompanion.Snapshot s&&s.objectId()==v.id()&&s.npcId()==v.npc()&&s.kind()==v.kind()&&s.x()==v.x()&&s.y()==v.y()&&s.heading()==v.heading()&&s.targetObjectId()==v.target();}
 // Retirement still owns same-object life changes. Only a different actor/birth may not borrow the earlier Snapshot.
 static BattleCompanion lookup(BattleCompanion pet,Object snapshot,Object choice){Object raw=raw(snapshot);if(!(choice instanceof NativeSourceNpcPlayer.Origin)||raw==null)return pet;return raw instanceof View v&&coherent(v,snapshot)&&pet!=null&&v.actor().get()==pet&&v.id()==(long)CombatAccess.field(pet,"objectId")?pet:null;}
 static boolean ready(ClientSession owner,BattleCompanion pet,long room,Object choice,Object snapshot){if(!NativeSourceCompanionClock.ready(owner,pet,room,choice))return false;Object raw=raw(snapshot);if(!(choice instanceof NativeSourceNpcPlayer.Origin)||raw==null)return true;return raw instanceof View v&&coherent(v,snapshot)&&same(v,pet)&&v.x()==(int)CombatAccess.field(pet,"x")&&v.y()==(int)CombatAccess.field(pet,"y")&&v.heading()==(int)CombatAccess.field(pet,"heading")&&v.target()==(long)CombatAccess.field(pet,"targetObjectId");}
 static NativeCombatAttacker.Ref ref(ClientSession owner,BattleCompanion pet,Object choice,Object snapshot){var ref=NativeSourceCompanionClock.ref(owner,pet,choice);Object raw=raw(snapshot);if(!(choice instanceof NativeSourceNpcPlayer.Origin)||raw==null||ref==null)return ref;if(!(raw instanceof View v)||!coherent(v,snapshot)||!same(v,pet)||ref.kind()!=2||ref.id()!=v.id()||ref.owner()!=v.life())return null;return new NativeCombatAttacker.Ref(ref.kind(),ref.id(),ref.owner(),ref.epoch(),ref.master(),ref.room(),ref.map(),ref.instance(),ref.nativeSourceNpcMasterProof,v);}
 static boolean live(boolean original,NativeCombatAttacker.Ref ref,Object actor){if(!original)return false;Object raw=ref.nativeSourceNpcTickView;if(raw==null)return true;return actor instanceof BattleCompanion pet&&Thread.holdsLock(pet)&&raw instanceof View v&&ref.id()==v.id()&&ref.owner()==v.life()&&same(v,pet);}
 private NativeSourceCompanionFirstActor(){}
}
